INSERT INTO change (id, date, author, module, summary, features, bugs, checks, review, approval) VALUES ('C-20261116-0191', '2026-11-16', 'Claude', 'src/memini/core/schema.py', 'graph schema v2: config/graph_schema.yaml declares the owner-approved 7 nodes and 11 relationships with scope/updated_by/updated_at on every node; schema.Property reads values, required and required_when, Relationship reads endpoint_offset; constraints are (scope, id) or (scope, name) per keyed label; 4 vector indexes', 'F-src/memini/core/schema.py-007', NULL, 'affected subset (graph, schema, v2, sanity) 364 passed on the Mac; ruff, ruff format, mypy src, deptry, lint-imports clean', NULL, 'owner 2026-11-16 "ok on schema and i want it to be implemented instead the old one"');
INSERT INTO change (id, date, author, module, summary, features, bugs, checks, review, approval) VALUES ('C-20261116-0192', '2026-11-16', 'Claude', 'src/memini/core/graph/', 'graph schema v2: Statement carries its scope and the kind delete; GraphSession records each run with its scope and sends a delete statement through the database guard first; PerfRecorder and QueryPerfLog take scope, graph_query_log has a scope column again (guarded ALTER for an older table)', 'F-src/memini/core/graph/-017,F-src/memini/core/graph/-018,F-src/memini/infra/graph/-004', NULL, 'affected subset (graph, schema, v2, sanity) 364 passed on the Mac; ruff, ruff format, mypy src, deptry, lint-imports clean', NULL, 'owner 2026-11-16 "ok on schema and i want it to be implemented instead the old one"');
INSERT INTO change (id, date, author, module, summary, features, bugs, checks, review, approval) VALUES ('C-20261116-0193', '2026-11-16', 'Claude', 'src/memini/core/graph/', 'graph schema v2: WriteBuilder is bound to a scope and a clock; node writes MERGE on (scope, id) or (scope, name) and set updated_by / updated_at; relationship ends are matched in the scope; values, required and required_when come from the schema; endpoint_offset adds the level WHERE and returns the count written; soft_delete / restore set status; hard_delete and hard_delete_scope need hard=True and build delete statements', 'F-src/memini/core/graph/-019,F-src/memini/core/graph/-020', NULL, 'affected subset (graph, schema, v2, sanity) 364 passed on the Mac; ruff, ruff format, mypy src, deptry, lint-imports clean', NULL, 'owner 2026-11-16 "ok on schema and i want it to be implemented instead the old one"');
INSERT INTO change (id, date, author, module, summary, features, bugs, checks, review, approval) VALUES ('C-20261116-0194', '2026-11-16', 'Claude', 'src/memini/core/graph/', 'QA: graph schema v2 tests for endpoint rules from the schema (endpoint_offset level checks returning the count written, allowed pairs for RELATED_TO and SUPERSEDES, order only on HAS_CHUNK, SIMILAR and HIERARCHICAL_LINK directed)', NULL, NULL, 'ruff check + ruff format --check clean; on 4d8174c 5 red / 63 green in test_graph_schema_v2.py; affected subset 371/371 green on 4d8174c + pairs + no Chunk.order (scratch); 3 mutants caught', NULL, 'owner 2026-11-16 (relayed): schema rules read from the YAML and applied generically');
INSERT INTO change (id, date, author, module, summary, features, bugs, checks, review, approval) VALUES ('C-20261116-0195', '2026-11-16', 'Claude', 'src/memini/core/schema.py', 'graph schema v2 second round: Relationship.pairs read from the YAML (RELATED_TO Entity-Entity and Community-Community, SUPERSEDES the same label at both ends) and enforced by the write builder for any relationship; Chunk.order removed, order lives only on HAS_CHUNK (each fact once)', 'F-src/memini/core/schema.py-008,F-src/memini/core/graph/-021', NULL, 'affected subset (graph, schema, v2, sanity) 371 passed on the Mac; ruff, ruff format, mypy src, deptry, lint-imports clean', NULL, 'owner 2026-11-16 SCHEMA-TASK.md second-round points 2 and 4; "ok on schema and i want it to be implemented instead the old one"');
